'use strict';

// PURE_JS_ONLY_NO_NATIVE: generated bytes, filesystem providers and a prototype
// namespace only. No Machine construction, makeVm, loadExe or guest execution.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const { runnerCdOptions, openRunnerCd, withRunnerCd, runDos, runDosWithPre } = require('../tools/toyvm/run-dos');
const { Machine } = require('../tools/toyvm/dos');
const hash = b => crypto.createHash('sha256').update(b).digest('hex');
const cue = 'REM original metadata\nFILE "original.bin" BINARY\n TRACK 01 MODE1/2352\n INDEX 00 00:00:00\n INDEX 01 00:00:02\n TRACK 02 AUDIO\n INDEX 00 00:00:26\n INDEX 01 00:00:27\n';
function iso() {
  const b = Buffer.alloc(24 * 2048);
  const both16 = (at, n) => { b.writeUInt16LE(n, at); b.writeUInt16BE(n, at + 2); };
  const both32 = (at, n) => { b.writeUInt32LE(n, at); b.writeUInt32BE(n, at + 4); };
  function record(at, name, lba, length, flags) {
    const id = typeof name === 'number' ? Buffer.from([name]) : Buffer.from(name);
    const size = 33 + id.length + (id.length % 2 ? 0 : 1);
    b[at] = size; both32(at + 2, lba); both32(at + 10, length);
    b[at + 25] = flags; both16(at + 28, 1); b[at + 32] = id.length; b.set(id, at + 33);
    return size;
  }
  const p = 16 * 2048;
  b.set([1, 67, 68, 48, 48, 49, 1], p); b.write('RUNNER_CD', p + 40);
  both32(p + 80, 24); both16(p + 128, 2048); record(p + 156, 0, 20, 2048, 2);
  b.set([255, 67, 68, 48, 48, 49, 1], 17 * 2048);
  let at = 20 * 2048;
  at += record(at, 0, 20, 2048, 2); at += record(at, 1, 20, 2048, 2);
  record(at, 'DATA.TXT;1', 21, 8, 0); b.write('original', 21 * 2048);
  return b;
}
function raw() {
  const b = iso(), out = Buffer.alloc(29 * 2352, 0xa7);
  for (let i = 0; i < 24; i++) {
    const at = (i + 2) * 2352;
    out[at] = out[at + 11] = 0; out.fill(255, at + 1, at + 11); out[at + 15] = 1;
    out.set(b.subarray(i * 2048, (i + 1) * 2048), at + 16);
  }
  return out;
}
function namespace() {
  return Object.assign(Object.create(Machine.prototype), { currentDrive: 2, currentDirectory: '',
    floppyVolumes: new Map(), isoVolumes: new Map(), driveDirectories: new Map([[0, ''], [1, ''], [2, '']]),
    mediaChanges: [] });
}
function contents(m, drive = 3) { return Buffer.from(m.isoVolumes.get(drive).entries.get('data.txt').read()).toString(); }
function fixture(fn) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'toyvm-runner-cd-'));
  try {
    const image = path.join(dir, 'original.iso'), bin = path.join(dir, 'supplied.bin'), cuePath = path.join(dir, 'original.cue');
    fs.writeFileSync(image, iso()); fs.writeFileSync(bin, raw()); fs.writeFileSync(cuePath, cue);
    return fn({ image, bin, cuePath });
  } finally { fs.rmSync(dir, { recursive: true, force: true }); }
}
async function asyncFixture(fn) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'toyvm-runner-cd-'));
  try {
    const image = path.join(dir, 'original.iso'), bin = path.join(dir, 'supplied.bin');
    fs.writeFileSync(image, iso()); fs.writeFileSync(bin, raw());
    return await fn({ image, bin });
  } finally { fs.rmSync(dir, { recursive: true, force: true }); }
}
// Observe the actual owned fd and close count, without relying on /proc layout.
async function descriptors(fn) {
  const open = fs.openSync, close = fs.closeSync, owned = new Map();
  fs.openSync = function(file, mode, ...args) {
    const fd = open.call(this, file, mode, ...args); owned.set(fd, { mode, closes: 0 }); return fd;
  };
  fs.closeSync = function(fd) { if (owned.has(fd)) owned.get(fd).closes++; return close.call(this, fd); };
  try { await fn(owned); }
  finally { fs.openSync = open; fs.closeSync = close; }
}

test('explicit options: defaults, collisions, missing pairs, reserved drives, batch allowed, no pre', async () => {
  assert.equal(runnerCdOptions({}), null);
  assert.deepEqual(runnerCdOptions({ cdIso: iso(), exe: 'INSTALL.BAT' }), { kind: 'iso', drive: 'D' });
  assert.deepEqual(runnerCdOptions({ cdIso: iso(), initialFloppy: Buffer.alloc(1), program: 'A:/GO.COM' }), { kind: 'iso', drive: 'D' });
  assert.deepEqual(runnerCdOptions({ cdCueText: cue, cdBin: raw(), cdDrive: 'z:' }), { kind: 'mixed', drive: 'Z' });
  for (const options of [{ cdDrive: 'D' }, { cdIso: iso(), cdBin: raw() }, { cdCueText: cue },
    { cdBin: raw() }, { cdCueText: cue, cdCue: 'x', cdBin: raw() },
    ...['A', 'B', 'C', 3, null, 'DD'].map(cdDrive => ({ cdIso: iso(), cdDrive })),
    { cdIso: iso(), pre: 'SETUP.COM' }]) {
    assert.throws(() => runnerCdOptions(options), /CD|cd|mixed|use /);
    // These reject in the wrapper before a Machine or controller can exist.
    await assert.rejects(runDos(options), /CD|cd|mixed|use /);
  }
  await assert.rejects(runDosWithPre({ cdIso: iso(), pre: 'SETUP.COM' }), /support pre/);
});

test('batch descendants borrow one actual ISO/BIN fd until final settlement, including late failure', async () => asyncFixture(async ({ image, bin }) => {
  for (const media of [{ cdIso: image }, { cdCueText: cue, cdBin: bin }]) {
    for (const fail of [false, true]) await descriptors(async owned => {
      let mount;
      const job = withRunnerCd({ ...media, exe: 'INSTALL.BAT' }, async (cd, options) => {
        mount = cd;
        for (let i = 0; i < 2; i++) {
          await withRunnerCd({ ...options, exe: 'SETUP.EXE' }, async (child, childOptions) => {
            assert.equal(child, cd);
            assert.equal(childOptions.exe, 'SETUP.EXE');
            const m = namespace(); child.mount(m);
            assert.equal(m.isoVolumes.get(3).media.source, cd.source);
            assert.equal(m.isoVolumes.get(3).media.cdromMedia, cd.disc);
            await Promise.resolve();
            assert.equal(contents(m), 'original');
            assert.equal(owned.size, 1);
            assert.equal([...owned.values()][0].closes, 0);
            if (fail && i === 1) throw Error('late batch error');
          });
          assert.equal([...owned.values()][0].closes, 0);
        }
      });
      if (fail) await assert.rejects(job, /late batch error/); else await job;
      assert.equal(owned.size, 1);
      assert.equal([...owned.values()][0].closes, 1);
      assert.throws(() => mount.source.readRange(0, 1), /closed/);
    });
  }
}));

test('no-CD path opens nothing and preserves callback result/error', async () => {
  await descriptors(async owned => {
    const result = {};
    assert.equal(await withRunnerCd({}, cd => { assert.equal(cd, null); return result; }), result);
    await assert.rejects(withRunnerCd({}, async cd => { assert.equal(cd, null); throw Error('ordinary failure'); }), /ordinary failure/);
    assert.equal(owned.size, 0);
  });
});

test('batch controlled input stays explicitly unsupported and closes media before creating a controller or Machine', async () => asyncFixture(async ({ image }) => {
  await descriptors(async owned => {
    await assert.rejects(runDos({ exe: 'INSTALL.BAT', cdIso: image,
      controlledInput: { mode: 'persistent' }, budget: 10, seconds: 1 }), /requires one direct program/);
    assert.equal(owned.size, 1); assert.equal([...owned.values()][0].closes, 1);
  });
}));

test('ISO borrowed provider identity, lazy namespace, C/A/B and caller lifetime preserved', async () => {
  const b = iso(), reads = [], before = hash(b); let closes = 0;
  const source = { size: b.length, readRange(o, n) { reads.push([o, n]); return b.subarray(o, o + n); }, close() { closes++; } };
  const m = namespace(), a = {}, boot = Buffer.from('boot'); m.floppyVolumes.set(0, a); m.floppyVolumes.set(1, boot);
  await withRunnerCd({ cdIso: source }, async cd => {
    cd.mount(m);
    assert.equal(m.isoVolumes.get(3).media.source, source);
    assert.equal(m.isoVolumes.get(3).media.cdromMedia, undefined);
    assert(reads.every(([o]) => o < 21 * 2048));
    assert.equal(contents(m), 'original');
    assert.equal(m.currentDrive, 2); assert.equal(m.currentDirectory, '');
    assert.equal(m.floppyVolumes.get(0), a); assert.equal(m.floppyVolumes.get(1), boot);
  });
  assert.equal(closes, 0); assert.equal(hash(b), before);
  assert.equal(contents(m), 'original'); // borrowed provider still belongs to caller
});

test('plain ISO byte input retains a synchronous sector provider for downstream services', async () => {
  const b = iso();
  await withRunnerCd({ cdIso: b }, cd => {
    const m = namespace(); cd.mount(m);
    const source = m.isoVolumes.get(3).media.source;
    assert.equal(source.size, b.length);
    assert.deepEqual(source.readRange(16 * 2048, 2048), b.subarray(16 * 2048, 17 * 2048));
    assert.equal(contents(m), 'original');
  });
});

test('mixed disc stays original: provider identity, CUE, INDEX00/01, raw audio and logical ISO', async () => {
  const b = raw(), before = hash(b);
  await withRunnerCd({ cdCueText: cue, cdBin: b, cdDrive: 'E:' }, async cd => {
    const m = namespace(); cd.mount(m);
    const media = m.isoVolumes.get(4).media;
    assert.equal(media.source, cd.source); assert.equal(media.cdromMedia, cd.disc);
    assert.equal(cd.disc.cueText, cue); assert.equal(cd.disc.file, 'original.bin');
    assert.equal(cd.disc.tracks.length, 2); assert.equal(cd.disc.tracks[1].isAudio, true);
    assert.equal(cd.disc.tracks[1].index00, 26); assert.equal(cd.disc.tracks[1].index01, 27);
    assert.equal(cd.source.size, 24 * 2048); assert.equal(cd.disc.size, b.length);
    assert.equal(contents(m, 4), 'original');
    assert.deepEqual(cd.disc.readSector(27), Uint8Array.from(b.subarray(27 * 2352, 28 * 2352)));
  });
  assert.equal(hash(b), before);
});

test('explicit CUE/BIN paths never resolve CUE FILE on the host; close is idempotent', () => fixture(({ bin, cuePath }) => {
  const before = hash(fs.readFileSync(bin));
  const cd = openRunnerCd({ cdCue: cuePath, cdBin: bin });
  const m = namespace(); cd.mount(m); assert.equal(contents(m), 'original');
  assert.equal(cd.disc.file, 'original.bin'); // actual supplied path is supplied.bin
  cd.close(); cd.close();
  assert.throws(() => cd.disc.readSector(27), /closed/);
  assert.throws(() => cd.mount(namespace()), /closed/);
  assert.equal(hash(fs.readFileSync(bin)), before);
}));

test('owned ISO/BIN fds close exactly once after awaited success and any callback error', async () => asyncFixture(async ({ image, bin }) => {
  for (const options of [{ cdIso: image }, { cdCueText: cue, cdBin: bin }]) {
    for (const phase of ['success', 'beforeMount', 'afterMount']) await descriptors(async owned => {
      let saved;
      const job = withRunnerCd(options, async cd => {
        saved = cd;
        assert.equal(owned.size, 1); assert.equal([...owned.values()][0].mode, 'r');
        if (phase === 'beforeMount') throw Error(phase);
        const m = namespace(); cd.mount(m); await Promise.resolve();
        assert.equal(contents(m), 'original');
        assert.equal([...owned.values()][0].closes, 0);
        if (phase === 'afterMount') throw Error(phase);
        return 17;
      });
      if (phase === 'success') assert.equal(await job, 17);
      else await assert.rejects(job, new RegExp(phase));
      assert.equal([...owned.values()][0].closes, 1);
      saved.close(); assert.equal([...owned.values()][0].closes, 1);
      assert.throws(() => saved.source.readRange(0, 1), /closed/);
    });
  }
}));

test('mount parse/collision failures and raw setup failures close fd before any handoff', async () => asyncFixture(async ({ image, bin }) => {
  await descriptors(async owned => {
    fs.truncateSync(image, 100);
    let handoffs = 0;
    await assert.rejects(withRunnerCd({ cdIso: image }, cd => {
      cd.mount(namespace()); handoffs++;
    }), /multiple|small/);
    assert.equal(handoffs, 0); assert.equal([...owned.values()][0].closes, 1);
  });
  await descriptors(async owned => {
    const m = namespace(), existing = {}; m.isoVolumes.set(3, existing);
    await assert.rejects(withRunnerCd({ cdCueText: cue, cdBin: bin }, cd => cd.mount(m)), /already mounted/);
    assert.equal(m.isoVolumes.get(3), existing); assert.equal(m.mediaChanges.length, 0);
    assert.equal([...owned.values()][0].closes, 1);
  });
  for (const text of ['bad cue', cue.replace('MODE1/2352', 'AUDIO')]) await descriptors(async owned => {
    assert.throws(() => openRunnerCd({ cdCueText: text, cdBin: bin }), /CUE|data track/);
    assert.equal([...owned.values()][0].closes, 1);
  });
}));

test('filesystem provider refuses truncation/bounds and keeps original bytes unchanged', () => fixture(({ image }) => {
  const before = hash(fs.readFileSync(image)), cd = openRunnerCd({ cdIso: image });
  try {
    const m = namespace(); cd.mount(m); assert.equal(contents(m), 'original');
    for (const [o, n] of [[-1, 1], [0, -1], [24 * 2048, 1], [0.5, 1]]) {
      assert.throws(() => cd.source.readRange(o, n), /bounds/);
    }
    assert.equal(hash(fs.readFileSync(image)), before);
    fs.truncateSync(image, 21 * 2048);
    assert.throws(() => contents(m), /short file read/);
  } finally { cd.close(); }
}));

test('missing/nonregular media and invalid provider fail without opening a namespace', () => fixture(({ image }) => {
  assert.throws(() => openRunnerCd({ cdIso: image + '.missing' }), /ENOENT/);
  assert.throws(() => openRunnerCd({ cdIso: path.dirname(image) }), /regular file/);
  for (const source of [null, {}, { size: 100, readRange: async () => new Uint8Array(100) }]) {
    const cd = openRunnerCd({ cdIso: source }), m = namespace();
    try { assert.throws(() => cd.mount(m)); assert.equal(m.isoVolumes.size, 0); }
    finally { cd.close(); }
  }
}));
